{{ config(
            materialized='table',
                post_hook={
                    "sql": "INSERT INTO snitch_db.maplemonk.offline_master_Daily_Report_1 (\"SKU_GROUP\", \"BRANCH_CODE\", \"MARKETPLACE_MAPPED\", \"FIRST_ORDER_DATE\", \"TOTAL_SALES\", \"TOTAL_RETURNS\", \"DAYS_SINCE_FIRST_ORDER\", \"AVERAGE_RETURN_SINCE_FIRST_ORDER\", \"NATURAL_ROS\", \"FINAL_ROS\", \"SALES_FIRST_7_DAYS\", \"SALES_FIRST_15_DAYS\", \"SALES_FIRST_30_DAYS\", \"SALES_LAST_7_DAYS\", \"SALES_LAST_15_DAYS\", \"SALES_LAST_30_DAYS\", \"INVENTORY\", \"XS_UNITS\", \"S_UNITS\", \"M_UNITS\", \"L_UNITS\", \"XL_UNITS\", \"XXL_UNITS\", \"XL3_UNITS\", \"XL4_UNITS\", \"XL5_UNITS\", \"XL6_UNITS\", \"NUM_SIZE_AVAILABLE\", \"FRESH_INVENTORY\", \"JIT_XS_UNITS\", \"JIT_S_UNITS\", \"JIT_M_UNITS\", \"JIT_L_UNITS\", \"JIT_XL_UNITS\", \"JIT_2XL_UNITS\", \"JIT_3XL_UNITS\", \"JIT_4XL_UNITS\", \"JIT_5XL_UNITS\", \"JIT_6XL_UNITS\", \"JIT_QTY\", \"CUT_SIZE_WITH_JIT_FLAG\", \"CUT_SIZE_FLAG\", \"DESIGNS\", \"NEW_CATEGORY\", \"COLLAR_NEW\", \"MATERIAL_NEW\", \"OCCASSION_NEW\", \"PRINT_DESIGN\", \"SLEEVE_TYPE\", \"FIT\", \"STYLE\", \"COLOR\", \"CUMULATIVE_SHARE\", \"PERCENTAGE_CATEGORY\", \"SKU_CLASS\", \"ONLINE_FINAL_ROS\", \"ONLINE_NATURAL_ROS\", \"CLUSTER\", \"BOH_AREA\", \"BASE_STOCK\", \"CARPET_AREA\", \"VM_OPTION\", \"DEPT_IDEAL\", \"AM\", \"RM\", \"NSM\", \"CITY\", \"STATE\", \"REGION\", \"PARTNER\", \"DATE\") SELECT \"SKU_GROUP\", \"BRANCH_CODE\", \"MARKETPLACE_MAPPED\", \"FIRST_ORDER_DATE\", \"TOTAL_SALES\", \"TOTAL_RETURNS\", \"DAYS_SINCE_FIRST_ORDER\", \"AVERAGE_RETURN_SINCE_FIRST_ORDER\", \"NATURAL_ROS\", \"FINAL_ROS\", \"SALES_FIRST_7_DAYS\", \"SALES_FIRST_15_DAYS\", \"SALES_FIRST_30_DAYS\", \"SALES_LAST_7_DAYS\", \"SALES_LAST_15_DAYS\", \"SALES_LAST_30_DAYS\", \"INVENTORY\", \"XS_UNITS\", \"S_UNITS\", \"M_UNITS\", \"L_UNITS\", \"XL_UNITS\", \"XXL_UNITS\", \"XL3_UNITS\", \"XL4_UNITS\", \"XL5_UNITS\", \"XL6_UNITS\", \"NUM_SIZE_AVAILABLE\", \"FRESH_INVENTORY\", \"JIT_XS_UNITS\", \"JIT_S_UNITS\", \"JIT_M_UNITS\", \"JIT_L_UNITS\", \"JIT_XL_UNITS\", \"JIT_2XL_UNITS\", \"JIT_3XL_UNITS\", \"JIT_4XL_UNITS\", \"JIT_5XL_UNITS\", \"JIT_6XL_UNITS\", \"JIT_QTY\", \"CUT_SIZE_WITH_JIT_FLAG\", \"CUT_SIZE_FLAG\", \"DESIGNS\", \"NEW_CATEGORY\", \"COLLAR_NEW\", \"MATERIAL_NEW\", \"OCCASSION_NEW\", \"PRINT_DESIGN\", \"SLEEVE_TYPE\", \"FIT\", \"STYLE\", \"COLOR\", \"CUMULATIVE_SHARE\", \"PERCENTAGE_CATEGORY\", \"SKU_CLASS\", \"ONLINE_FINAL_ROS\", \"ONLINE_NATURAL_ROS\", \"CLUSTER\", \"BOH_AREA\", \"BASE_STOCK\", \"CARPET_AREA\", \"VM_OPTION\", \"DEPT_IDEAL\", \"AM\", \"RM\", \"NSM\", \"CITY\", \"STATE\", \"REGION\", \"PARTNER\", current_date as date FROM snitch_db.maplemonk.offline_master where not exists ( SELECT 1 AS Exist FROM snitch_db.maplemonk.offline_master_Daily_Report_1 WHERE DATE = CURRENT_DATE() LIMIT 1) ; INSERT INTO SNITCH_DB.MAPLEMONK.OFFLINE_METAFIELD_IDEAL_MIX_V2_DAILY WITH category_mix AS ( SELECT TRIM(UPPER(STORE_CODE)) AS branch_code, UPPER(TRIM(category)) AS category, CAST(NULLIF(TRIM(CATEGORY_MIX), \'\') AS DECIMAL(10,4)) AS category_ideal_mix_pct FROM SNITCH_DB.MAPLEMONK.CATEGORY_MIX WHERE CATEGORY_MIX IS NOT NULL ), metafield_mix AS ( SELECT TRIM(UPPER(branch_code)) AS branch_code, TRIM(UPPER(style)) AS style, UPPER(TRIM(category_name)) AS category, CASE WHEN TRIM(UPPER(style)) = \'LUXE\' THEN \'0\' ELSE COALESCE(TRIM(UPPER(meta_1)), \'N/A\') END AS meta_1, CASE WHEN TRIM(UPPER(style)) = \'LUXE\' THEN \'0\' ELSE COALESCE(TRIM(UPPER(meta_2)), \'N/A\') END AS meta_2, CASE WHEN TRIM(UPPER(style)) = \'LUXE\' THEN \'0\' ELSE COALESCE(TRIM(UPPER(meta_3)), \'N/A\') END AS meta_3, CAST(NULLIF(TRIM(MIX), \'\') AS DECIMAL(10,4)) AS meta_mix_pct FROM ( SELECT *, \'T-SHIRTS\' AS category_name FROM SNITCH_DB.MAPLEMONK.OFFLINE_T_SHIRTS_MIX UNION ALL SELECT *, \'SHIRTS\' AS category_name FROM SNITCH_DB.MAPLEMONK.OFFLINE_SHIRTS_MIX UNION ALL SELECT *, \'TROUSERS\' AS category_name FROM SNITCH_DB.MAPLEMONK.OFFLINE_TROUSERS_MIX UNION ALL SELECT *, \'JEANS\' AS category_name FROM SNITCH_DB.MAPLEMONK.OFFLINE_JEANS_MIX ) ), meta_computed AS ( SELECT m.branch_code, m.style, m.category, m.meta_1, m.meta_2, m.meta_3, m.meta_mix_pct, c.category_ideal_mix_pct, ROUND(m.meta_mix_pct * c.category_ideal_mix_pct, 6) AS metafield_ideal_mix FROM metafield_mix m JOIN category_mix c ON m.branch_code = c.branch_code AND m.category = c.category WHERE m.meta_mix_pct > 0 ), fallback_general AS ( SELECT c.branch_code, \'SNITCH\' AS style, c.category, \'N/A\' AS meta_1, \'N/A\' AS meta_2, \'N/A\' AS meta_3, 1.0000 AS meta_mix_pct, c.category_ideal_mix_pct, c.category_ideal_mix_pct AS metafield_ideal_mix FROM category_mix c WHERE c.category NOT IN (\'T-SHIRTS\', \'SHIRTS\', \'TROUSERS\', \'JEANS\') AND c.category_ideal_mix_pct > 0 ) SELECT *, CURRENT_DATE AS snapshot_date FROM meta_computed UNION ALL SELECT *, CURRENT_DATE AS snapshot_date FROM fallback_general; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.OFFLINE_METAFIELD_GAPS_DAILY AS WITH METAFIELDS_STD AS ( SELECT OM.SKU_GROUP, MAX(UPPER(OM.NEW_CATEGORY)) AS CATEGORY, MAX( CASE WHEN UPPER(OM.SKU_GROUP) LIKE \'%LX%\' OR UPPER(OM.STYLE) LIKE \'%LUXE%\' THEN \'LUXE\' WHEN UPPER(OM.SKU_GROUP) LIKE \'%4MBG%\' OR UPPER(OM.STYLE) LIKE \'%PLUS%\' THEN \'PLUS\' ELSE \'SNITCH\' END ) AS STYLE, MAX( CASE WHEN UPPER(OM.NEW_CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN TRIM(LOWER(OM.COLLAR_NEW)) IN (\'mock\',\'spread\',\'cuban\',\'mandarin\',\'polo\',\'high neck\',\'zip\',\'baseball\',\'collar\') THEN \'POLO\' ELSE \'ROUND\' END WHEN UPPER(OM.NEW_CATEGORY) = \'SHIRTS\' THEN CASE WHEN (LOWER(OM.STYLE) LIKE \'%linen%\' OR UPPER(OM.MATERIAL_NEW) = \'LINEN\') THEN \'LINEN\' WHEN UPPER(OM.MATERIAL_NEW) = \'COTTON\' THEN \'COTTON\' ELSE \'POLYESTER\' END WHEN UPPER(OM.NEW_CATEGORY) IN (\'TROUSERS\',\'CHINOS\') THEN CASE WHEN UPPER(OM.FIT) IN (\'REGULAR FIT\',\'CARROT FIT\',\'COMFORT FIT\',\'STRAIGHT FIT\',\'CUSTOM FIT\') THEN \'STRAIGHT FIT\' WHEN UPPER(OM.FIT) IN (\'RELAXED FIT\',\'LOOSE FIT\',\'WIDE FIT\',\'BAGGY FIT\') THEN \'BAGGY FIT\' WHEN UPPER(OM.FIT) = \'SLIM FIT\' THEN \'SLIM FIT\' ELSE \'STRAIGHT FIT\' END WHEN UPPER(OM.NEW_CATEGORY) = \'JEANS\' THEN CASE WHEN UPPER(OM.FIT) IN (\'TAPERED FIT\',\'REGULAR FIT\',\'RELAXED FIT\',\'STRAIGHT FIT\',\'COMFORT FIT\') THEN \'STRAIGHT FIT\' WHEN UPPER(OM.FIT) IN (\'SUPER BAGGY FIT\',\'SLOUCHY FIT\',\'BAGGY FIT\') THEN \'BAGGY FIT\' WHEN UPPER(OM.FIT) IN (\'LOOSE FIT\',\'STRAIGHT LOOSE FIT\') THEN \'STRAIGHT LOOSE FIT\' WHEN UPPER(OM.FIT) IN (\'BOOTCUT\',\'FLARED FIT\') THEN \'BOOTCUT\' WHEN UPPER(OM.FIT) IN (\'CARROT FIT\',\'BALLOON FIT\') THEN \'CARROT FIT\' WHEN UPPER(OM.FIT) = \'SLIM FIT\' THEN \'SLIM FIT\' WHEN UPPER(OM.FIT) = \'SKINNY FIT\' THEN \'SKINNY FIT\' ELSE \'STRAIGHT FIT\' END END ) AS META1, MAX( CASE WHEN UPPER(OM.NEW_CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN (UPPER(TRIM(OM.STYLE)) LIKE \'%TECHNICAL%\' OR UPPER(TRIM(OM.STYLE)) LIKE \'%STITCHLESS%\') THEN \'TECHNICAL\' WHEN UPPER(TRIM(OM.DESIGNS)) = \'SOLID\' THEN \'CORE\' ELSE \'FASHION\' END WHEN UPPER(OM.NEW_CATEGORY) = \'SHIRTS\' THEN CASE WHEN (UPPER(TRIM(OM.STYLE)) LIKE \'%TECHNICAL%\' OR UPPER(TRIM(OM.STYLE)) LIKE \'%STITCHLESS%\') THEN \'TECHNICAL\' WHEN UPPER(TRIM(OM.DESIGNS)) = \'SOLID\' THEN \'SOLID\' WHEN UPPER(TRIM(OM.DESIGNS)) = \'STRIPES\' THEN \'STRIPES\' WHEN UPPER(TRIM(OM.DESIGNS)) IN (\'TEXTURED\',\'SELF DESIGN\') THEN \'SELF DESIGN & TEXTURED\' WHEN UPPER(TRIM(OM.DESIGNS)) = \'CHECKS\' THEN \'CHECKS\' WHEN UPPER(TRIM(OM.DESIGNS)) = \'EMBROIDED\' THEN \'EMBROIDED\' WHEN UPPER(TRIM(OM.DESIGNS)) = \'EMBELLISHED\' THEN \'EMBELLISHED\' ELSE \'PRINTED\' END END ) AS META2, MAX( CASE WHEN UPPER(OM.NEW_CATEGORY) = \'T-SHIRTS\' THEN CASE WHEN UPPER(TRIM(OM.FIT)) IN (\'OVERSIZED\',\'BOX FIT\',\'RELAXED FIT\') THEN \'OVERSIZED FIT\' WHEN UPPER(TRIM(OM.FIT)) = \'SLIM FIT\' THEN \'SLIM FIT\' ELSE \'REGULAR FIT\' END END ) AS META3 FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER OM WHERE UPPER(OM.NEW_CATEGORY) NOT IN (\'BAGS\',\'BELTS\',\'SHOES\',\'SUNGLASSES\',\'PERFUMES\') GROUP BY OM.SKU_GROUP ), INV_DAILY_TAGGED AS ( SELECT DATE_TRUNC(\'WEEK\', R.DATE) AS WEEK_START, R.DATE, R.BRANCH_CODE, COALESCE(UPPER(TRIM(MS.CATEGORY)), \'NO_CATEGORY\') AS CATEGORY, COALESCE(UPPER(TRIM(MS.STYLE)), \'SNITCH\') AS STYLE, CASE WHEN COALESCE(UPPER(TRIM(MS.STYLE)),\'SNITCH\') = \'LUXE\' THEN \'0\' ELSE COALESCE(UPPER(TRIM(MS.META1)),\'N/A\') END AS META1, CASE WHEN COALESCE(UPPER(TRIM(MS.STYLE)),\'SNITCH\') = \'LUXE\' THEN \'0\' ELSE COALESCE(UPPER(TRIM(MS.META2)),\'N/A\') END AS META2, CASE WHEN COALESCE(UPPER(TRIM(MS.STYLE)),\'SNITCH\') = \'LUXE\' THEN \'0\' ELSE COALESCE(UPPER(TRIM(MS.META3)),\'N/A\') END AS META3, SUM(R.INVENTORY + R.JIT_QTY) AS TOTAL_INV FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER_DAILY_REPORT_1 R LEFT JOIN METAFIELDS_STD MS ON UPPER(R.SKU_GROUP) = UPPER(MS.SKU_GROUP) GROUP BY 1,2,3,4,5,6,7,8 ), INV_WEEKLY AS ( SELECT WEEK_START, BRANCH_CODE, CATEGORY, STYLE, META1, META2, META3, ROUND( ( SUM(CASE WHEN DATE = MIN_DATE THEN TOTAL_INV END) + SUM(CASE WHEN DATE = MAX_DATE THEN TOTAL_INV END) ) / 2.0 , 0) AS TOTAL_INV FROM ( SELECT T.*, MIN(DATE) OVER (PARTITION BY WEEK_START, BRANCH_CODE, CATEGORY, STYLE, META1, META2, META3) AS MIN_DATE, MAX(DATE) OVER (PARTITION BY WEEK_START, BRANCH_CODE, CATEGORY, STYLE, META1, META2, META3) AS MAX_DATE FROM INV_DAILY_TAGGED T ) GROUP BY 1,2,3,4,5,6,7 ), SALES_WEEKLY AS ( SELECT DATE_TRUNC(\'WEEK\', S.ORDER_DATE) AS WEEK_START, S.BRANCH_CODE, COALESCE(UPPER(TRIM(MS.CATEGORY)), \'NO_CATEGORY\') AS CATEGORY, COALESCE(UPPER(TRIM(MS.STYLE)), \'SNITCH\') AS STYLE, CASE WHEN COALESCE(UPPER(TRIM(MS.STYLE)),\'SNITCH\') = \'LUXE\' THEN \'0\' ELSE COALESCE(UPPER(TRIM(MS.META1)),\'N/A\') END AS META1, CASE WHEN COALESCE(UPPER(TRIM(MS.STYLE)),\'SNITCH\') = \'LUXE\' THEN \'0\' ELSE COALESCE(UPPER(TRIM(MS.META2)),\'N/A\') END AS META2, CASE WHEN COALESCE(UPPER(TRIM(MS.STYLE)),\'SNITCH\') = \'LUXE\' THEN \'0\' ELSE COALESCE(UPPER(TRIM(MS.META3)),\'N/A\') END AS META3, SUM(S.SHIPPING_QUANTITY) AS SALES_QTY FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE S LEFT JOIN METAFIELDS_STD MS ON UPPER(S.SKU_GROUP) = UPPER(MS.SKU_GROUP) WHERE S.DOC_PREFIX NOT IN (\'OMS\',\'QCOM\') AND S.branch_code NOT IN (\'45\',\'59\',\'32\',\'9\',\'35\',\'33\',\'76\',\'94\',\'46\',\'10\',\'60\',\'2\',\'8\',\'133\') AND S.category_class IS NOT NULL AND S.category_class NOT IN (\'Blazers\',\'Boxers\',\'Inner Wear\',\'Night Suit & Pyjamas\',\'Pyjamas\',\'Co-ords\') AND LOWER(S.order_status) LIKE \'%process%\' AND S.sku_group NOT LIKE \'%CB%\' AND S.sku_group NOT LIKE \'%WBC%\' AND S.sku_group NOT LIKE \'8909%\' AND UPPER(S.sku_group) NOT LIKE \'UNIFORM%\' GROUP BY 1,2,3,4,5,6,7 ), INV_MIX AS ( SELECT *, ROUND(100.0 * TOTAL_INV / NULLIF(SUM(TOTAL_INV) OVER (PARTITION BY WEEK_START, BRANCH_CODE), 0), 2) AS INV_MIX_PCT FROM INV_WEEKLY ), SALES_MIX AS ( SELECT *, ROUND(100.0 * SALES_QTY / NULLIF(SUM(SALES_QTY) OVER (PARTITION BY WEEK_START, BRANCH_CODE), 0), 2) AS SALES_MIX_PCT FROM SALES_WEEKLY ) SELECT COALESCE(I.WEEK_START, S.WEEK_START) AS WEEK_START, COALESCE(I.BRANCH_CODE, S.BRANCH_CODE) AS BRANCH_CODE, COALESCE(I.CATEGORY, S.CATEGORY) AS CATEGORY, COALESCE(I.STYLE, S.STYLE) AS STYLE, COALESCE(I.META1, S.META1) AS META1, COALESCE(I.META2, S.META2) AS META2, COALESCE(I.META3, S.META3) AS META3, COALESCE(I.TOTAL_INV, 0) AS TOTAL_INV, COALESCE(I.INV_MIX_PCT, 0) AS INV_MIX_PCT, COALESCE(S.SALES_QTY, 0) AS SALES_QTY, COALESCE(S.SALES_MIX_PCT, 0) AS SALES_MIX_PCT FROM INV_MIX I FULL OUTER JOIN SALES_MIX S ON I.WEEK_START = S.WEEK_START AND I.BRANCH_CODE = S.BRANCH_CODE AND I.CATEGORY = S.CATEGORY AND I.STYLE = S.STYLE AND I.META1 = S.META1 AND I.META2 = S.META2 AND I.META3 = S.META3 ORDER BY 1, 2, 3, 5, 6, 7;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            